  "亚运会、世博会带来客流高峰，疫情与灾害使出行减少；每个阶段都有本城目标与阶段总结。": "The Asian Games and World Expos bring ridership peaks, while epidemics and disasters reduce travel; every phase has city goals and a phase summary.",
  "自由建造可选起始年份并解锁全图；香港海洋公园与迪士尼乐园加入专属模型与客流。": "Free Build can start in a later year and unlock the whole map; Hong Kong's Ocean Park and Disneyland get their own models and visitor demand.",
  "更稳定的城市经营": "More stable city management",
  "优化读档与切换进度，避免重复载入和过期任务干扰当前城市。": "Improve save loading and progress switching, preventing superseded requests from interfering with the current city.",
  "减少交通缓存与动画路径的重复计算，改善复杂线网的音效连续性。": "Reduce repeated work in traffic caches and animation paths, and preserve continuous audio on complex metro networks.",
  "整理冗余代码和构建文件，保留现有地图、玩法与存档兼容。": "Clean up unused code and generated build files while retaining maps, gameplay and save compatibility.",
  "恢复车流、人流的正常动画速度，1×、3×、8× 与列车共用倍速，主菜单与各视图保持统一。": "Restore normal car and pedestrian animation speeds. Cars, pedestrians and trains share 1x, 3x and 8x speed, consistently across views and the main menu.",
  "更轻快的城市经营": "Lighter, faster city management",
  "日常交通采用轻量更新，加快读档、跳月和长期经营，保留九张地图与现有建设功能。": "Lighter routine traffic updates speed up loading and time advancement, retaining all nine maps and construction features.",
  "重大建设增加交通计算，客流与拥堵任务接近奖惩门槛时复核，保护已有进度。": "Major construction receives additional traffic calculation. Passenger and congestion objectives are reviewed before threshold-sensitive outcomes.",
  "复用车辆转弯路径，减少重复计算及镜头边缘提前退场，保留连续移动与统一的视图表现。": "Shared turning paths reduce repeated work and premature exits near the camera edge, preserving continuous movement across views.",
