  "更快地载入，更顺畅地经营": "Faster loading, smoother management",
  "加快读档速度，同一进度再次载入可快速恢复交通状态。": "Faster loading, with quick traffic recovery when returning to the same save.",
  "优化交通计算和时间推进，保持客流、财政及任务结算一致。": "Optimized traffic calculations and time advancement while preserving passenger flows, finances and mission settlement.",
  "完善大学、会展和会议中心的整片浅色底板，保留道路与水域。": "Unified pale ground surfaces for campuses and exhibition or conference centres, with roads and water kept visible.",
  "早高峰主要道路拥堵指数变化不明显。新增地铁不保证道路拥堵一定改善。": "Morning-peak congestion on major roads changes little. A new metro does not guarantee that every road becomes less congested.",
