  "规模：估算": "Size: Estimated",
  "位置：真实地理": "Location: Real Geography",
  "年份：地标落成（史实）": "Date: Historical Landmark Completion",
  "杨浦大桥": "Yangpu Bridge",
  "卢浦大桥": "Lupu Bridge",
