  "地图展示更新": "Map display updated",
  "城市地图展示调整，原有线网与经营进度保留": "City display updated; your network and operating progress are retained",
  "地图展示已更新，原有线网与经营进度保留；升级前的存档已单独备份": "Map display updated. Your network and operating progress are retained; the original save has been backed up separately.",
  "地图展示已更新；升级前备份未能建立，不会自动保存，原存档保持不变": "Map display updated in memory. A pre-upgrade backup could not be created, so autosave is disabled and the original save is unchanged.",
  "汉口中部开始建设王家墩中央商务区。": "Wangjiadun Central Business District begins development in central Hankou.",
  "1995 年 4 月启用，承担武汉的民航。航站区在地图北缘，机场跑道一带不开发。": "Opened in April 1995, Tianhe handles Wuhan's civilian flights. Its terminal is near the northern map edge; the runway area is protected from development.",
  "2020 年之后的发展、居民出行选择、道路拥堵、客流与财政结果。普通铁路与高速铁路不参与乘客出行与运营模拟，车站与民用机场的旅客量为估算、只模拟其市内接驳出行；地面铁路按真实线位阻隔步行与小路；真实的杭州地铁不会自动出现。": "Post-2020 development, travel, congestion, ridership and finances are simulated. Ordinary and high-speed trains are outside the operating simulation; stations and civilian airports generate estimated urban connections. Surface tracks obstruct walking and minor roads. Real metro routes never appear automatically.",
  "本游戏需要启用 JavaScript。": "JavaScript must be enabled to play.",
