  "亚运会，广州塔落成": "Asian Games; Canton Tower completed",
  "1990 年的广州还没有一公里地铁。老城的街巷挤满公交与自行车，天河才刚刚起步，珠江新城仍是一片农田。你要在老城与天河之间画下第一条线，再跟着城市一路向东、向南跨过珠江。": "Guangzhou has no metro in 1990. Buses and bicycles crowd the old town, Tianhe is just emerging and Zhujiang New Town remains farmland. Draw the first line between the old town and Tianhe, then follow the city east and south across the Pearl River.",
