  "动态由本月的模拟数据生成：片区的地铁步行覆盖、新开车站、换乘步行距离、车站与列车的高峰拥挤、票价负担、道路拥堵与设施接驳；点赞数大致反映受影响的人数。": "Posts are generated from this month's simulation: metro walking coverage by district, new stations, transfer walking distances, peak crowding at stations and on trains, fare burden, road congestion and access to facilities. Like counts roughly reflect how many people are affected.",
