  "北京与更顺手的规划": "Beijing and Better Planning",
  "新增北京（1990 年起）：接管 1 号线与环线，沿环路规划城市；中关村、CBD、奥运场馆与城市副中心逐步发展，首都机场和大兴机场接驳需求按年代出现。": "Beijing starts in 1990: take over Line 1 and the loop Line 2. Zhongguancun, the CBD, Olympic venues, and the city subcenter develop over time; airport demand follows the era.",
  "任务目标更温和：拥堵与设施接驳任务不再计入临时降价的月份；偏远设施改为在附近设站并接入已有线网，减少又长又空的延伸。": "Task goals are gentler. Discounted-fare months do not count toward congestion or facility-share tasks; remote facilities ask for a connection to the existing network.",
  "已完成和未完成的任务可以展开查看完整目标、地点、完成时的结果与奖惩；最近结束的任务默认展开，方便回看。": "Expand completed or expired tasks to review their goals, locations, final results, and rewards. Recently finished tasks expand automatically.",
  "新增沉浸模式：在设置中开启或按 H 隐藏界面，只看城市；右上角保留恢复按钮，手机也可操作，使用建设或帮助快捷键时自动显示界面。": "Immersive mode hides the interface from Settings or the H key. A restore button remains available on phones; construction and help shortcuts reveal the interface.",
  "九种分析图层全部列入图层面板，按城市、交通和地铁分组排布，并避让图例、教程和建设工具；指标详情的图层开关随实际状态更新。": "All nine analysis layers are available in the grouped layer panel, positioned around legends, tutorials, and construction tools. Metric controls follow the active layer.",
  "修复分帧绘制时地面缺块、巴黎后期票价读档变低的问题；载入计算长期无响应时结束等待，保留原进度，并提供导出、其他存档和新建入口。": "Fixed missing map stripes and reduced Paris fares after loading. Stalled loading stops safely and offers export, other saves, and a new game while preserving current progress.",
