  "智能调度": "Smart Dispatch",
  "手动：每个时段投入几列由你设定（不超过配属列车）。多投入发车更密、运营费用更高；投入太少车厢拥挤、候车变长。": "Manual: you set how many trains run in each period, up to the trains assigned. More trains mean shorter headways and higher operating costs; too few means crowding and longer waits.",
  "智能调度：在配属列车范围内按客流与最低服务水平安排各时段投入的列车；列车不够时低运力运行，车厢拥挤、候车变长。": "Smart dispatch schedules the assigned trains in each period by demand and minimum service levels. If there are not enough trains, the line runs at reduced capacity with crowding and longer waits.",
