  "编组超过本线站台长度，调往其他线路或出售": "Train too long for this line's platforms. Move it to another line or sell it",
  "列车运营说明": "About Train Operations",
  "发车频率由投入的列车数决定：间隔 ≈ 周转时间 ÷ 投入列车数，最小 2 分钟；支线单独配车，环线两个方向分别配车。": "Frequency depends on the trains in service: headway ≈ round-trip time ÷ trains in service, at least 2 minutes. Branches have their own trains, and each direction of a loop line is staffed separately.",
  "买车按车型与编组整列购买，编组不能超过沿线最小车站的站台长度；车型按城市与年代开放。": "Trains are bought whole, by model and length. Length cannot exceed the shortest platform on the line. Models become available by city and era.",
  "运营按车厢公里计费，老车型与超龄列车更费钱；出售按残值回收（买价的 75% 起逐年折旧，最低 8%）。": "Operation is charged per car-kilometre, and older models and trains past their design life cost more. Sales return residual value: 75% of the price, depreciating each year to at least 8%.",
  "新线与延长按最低服务水平随线配车，费用计入建设；车辆段有闲置列车时先用闲置列车。": "New lines and extensions come with enough trains for minimum service, included in the construction cost. Idle depot trains are used first.",
