  "{v0} 早高峰满载率 {v1}，列车只有 {v2} 节。公司投资把沿线 {v3} 座车站升级为大型站、列车加长到 8 节；政府不给建设补助，改造完成后按可用性付费分 8 年支付。": "{v0} runs at {v1} of capacity in the morning peak with only {v2}-car trains. The company funds upgrading {v3} stations to large so trains can run 8 cars. There is no construction subsidy; the government pays availability payments over 8 years after completion.",
