  "高客流车站可以开发商业，换乘枢纽收益最高；开发后每年有运营与维护成本，客流太少会亏损。": "Busy stations can be developed for commerce, and interchanges earn most. Developments have yearly operating and upkeep costs, so quiet stations lose money.",
