  "每条线路最多加开 ": "Each line can add up to ",
  "每次建设完成都会生成「建设效果报告」，会告诉你为什么，在拥堵或分担率详情里也能打开。": "Every project produces a build impact report that explains why; open it from the congestion or mode share details too.",
  "点「列车运营」": "Click Train Operations",
  "点「购买列车」，买 1 列": "Click Buy Trains and buy 1",
  "点击改为停靠": "Click to stop here",
  "点击改为通过不停": "Click to pass without stopping",
  "点右下角的「地铁芯」": "Click MetroCore at the bottom right",
  "点顶栏的「任务」": "Click Tasks in the top bar",
  "片区详情会告诉你本地居民有多少开车、地铁能替代多少；点到道路也算完成。其他图层在左下「图层」面板。": "Area details show how many residents drive and how many the metro could carry; clicking a road also counts. Other layers are in the Layers panel at the bottom left.",
  "环状线": "Circular Line",
  "直通运转": "Through-Running",
  "看车站客流与拥挤": "Check Station Flows and Crowding",
  "真实城市里，线路或车站持续过载时，地铁芯入口上方会出现提醒：可以自动处理，也可以定位后手动处理。": "In real cities, when a line or station stays overloaded, a reminder appears above MetroCore: fix it automatically, or locate it and fix it yourself.",
  "票价与财政": "Fares and Finance",
  "票价越高收入越多，乘客越少。收入、运营费和债券都在财政页。": "Higher fares earn more but carry fewer riders. Income, operating costs and bonds are all on the Finance page.",
  "站站停 ": "All-stops ",
