  "旧城": "the old city",
  "回龙观与天通苑": "Huilongguan and Tiantongyuan",
  "江东": "Koto",
  "2016 年底前，步行 15 分钟可到达地铁站的人口不低于全市人口的 30%，而且汉口、汉阳、武昌三镇都要覆盖到，不能只顾一处。": "By the end of 2016, at least 30% of residents must live within a 15-minute walk of a station, and Hankou, Hanyang and Wuchang all have to be covered, not just one of them.",
  "连接沙田与九龙塘，穿越狮子山时可以建设山体隧道。铁路要带动新市镇：沙田的人步行能到车站，站城商业也要赚钱。": "Connect Sha Tin and Kowloon Tong, tunnelling under Lion Rock. The railway has to drive the new town: Sha Tin residents can walk to a station, and station commerce turns a profit.",
  "回归前，步行 15 分钟可到达地铁站的人口不低于全市人口的 50%，经营也要站得住：票款加车站商业连续 3 个月达到运营费用的 75%。": "Before the 1997 handover, at least 50% of residents must live within a 15-minute walk of a station, and the finances have to hold up: fares plus station commerce reach 75% of operating costs for 3 months in a row.",
  "新市镇隔着山与市区相望，人口快速增长，进城只能挤公路与隧道。铁路加物业是香港的办法：让荃湾、沙田接近一半的居民步行就能到地铁站，并在新市镇开发站城商业，形成正收益。": "The new towns sit behind the hills, growing fast, with only crowded roads and tunnels into town. Rail plus property is Hong Kong's answer: bring nearly half of Tsuen Wan and Sha Tin residents within walking distance of a station, and develop profitable station commerce in the new towns.",
  "客流大的新市镇车站先做商业开发，收益才能转正": "Develop the busiest new-town stations first so the commerce turns a profit",
  "连接木栅、东区与松山机场航站楼一侧。这是一条高架中运量线路：列车不超过 4 节，小半径穿过城区。机场照常运营，范围内只能地下设站或地下穿越。": "Connect Muzha, the East District and the Songshan Airport terminal side. This is an elevated medium-capacity line: trains of no more than 4 cars, threading the city on tight curves. The airport stays open, so within its grounds the line must stay underground.",
  "台北盆地被淡水河、基隆河与新店溪环绕，人口都挤在盆地里，走廊多而短。一条长线覆盖不了，要靠几条线交织、互相换乘：建成 4 座换乘站，而且换乘客流不能都压在台北车站。": "The Taipei Basin is ringed by the Tamsui, Keelung and Xindian rivers. People crowd into the basin along many short corridors, too many for one long line. Weave several lines together: build 4 interchange stations, without loading every transfer onto Taipei Main Station.",
  "沿旧包税人城墙的林荫大道，连接星形广场、克利希广场、巴尔贝斯、斯大林格勒与民族广场。这段地势起伏，可以像当年一样修成高架。": "Along the boulevards of the old Farmers-General wall, connect Étoile, Place de Clichy, Barbès, Stalingrad and Nation. The ground rises and falls here, so it can run on a viaduct as it did historically.",
  "新商务区需要快速、长站距的东西向干线：由同一条线连接拉德芳斯、星形广场、奥柏与民族广场，平均站距不少于 1.5 km。": "The new business district needs a fast east–west trunk with long station spacing: one line connecting La Défense, Étoile, Auber and Nation, with stations at least 1.5 km apart on average.",
  "回龙观、上地与望京的居民需要进城。连接西直门、五道口、上地、回龙观与东直门。北部空地多，可以像城市铁路那样走地面和高架，把造价压下来。": "Residents of Huilongguan, Shangdi and Wangjing need a way into town. Connect Xizhimen, Wudaokou, Shangdi, Huilongguan and Dongzhimen. The north has open land, so run on the surface and on viaducts like the Urban Railway to hold down the cost.",
  "北京的道路是一环套一环，地铁也需要环线把放射线串起来，乘客不必都挤进旧城换乘。修一条环绕旧城、35 km 以上的大环线，与至少 4 条放射线换乘（一头在环内、一头在环外），全网 12 座以上换乘站，旧城的换乘客流降到六成以下。": "Beijing's roads form ring upon ring, and the metro needs a loop to tie its radial lines together so passengers need not crowd into the old city to change. Build a large loop of at least 35 km around the old city, interchanging with at least 4 radial lines (one end inside the loop, one outside), reach 12 interchange stations across the network, and cut the old city's share of transfers below 60%.",
  "在三环、四环附近再修一条环线，比开局的 2 号线大一圈": "Build another loop near the 3rd and 4th ring roads, one size larger than the original Line 2",
